SELECT point_code, COUNT(*) AS n, SUM(CASE WHEN correct = 0 THEN 1 ELSE 0 END) AS wrong, COUNT(DISTINCT CASE WHEN correct = 0 THEN learner END) AS learners FROM progress_answer WHERE subject_id = CAST(:subject AS INTEGER) AND substr(at, 1, 10) >= :since AND instr(:names, '|' || learner || '|') > 0 GROUP BY point_code HAVING SUM(CASE WHEN correct = 0 THEN 1 ELSE 0 END) > 0 ORDER BY wrong DESC, (SUM(CASE WHEN correct = 0 THEN 1 ELSE 0 END) * 1.0 / COUNT(*)) DESC, point_code ASC
